import{_ as o,l as r,o as e,c as n,v as t,p as s,x as l,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"潜空间与 VAE","description":"","frontmatter":{"title":"潜空间与 VAE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/latent-vae.md","filePath":"llm/latent-vae.md","lastUpdated":1789023840000}'),E={name:"llm/latent-vae.md"};function p(A,a,c,_,f,D){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="潜空间与-vae" tabindex="-1">潜空间与 VAE <a class="header-anchor" href="#潜空间与-vae" aria-label="Permalink to &quot;潜空间与 VAE&quot;">​</a></h1><div class="epigraph"><p>先把图压进低维连续潜变量，再在潜空间里扩散或流。像素解码器负责纹理，生成器不必每步在 RGB 上跑。</p><footer>—— Kingma, Welling, VAE；Rombach 等 Latent Diffusion / Stable Diffusion</footer></div><p><a href="/llm/flow-matching">上一课</a>与 <a href="/llm/ddpm">DDPM</a> 都可以在数据空间做。缺口是算力：高分辨率 RGB 上每步 U-Net 不可扩展。Rombach 等人先训感知压缩的 VAE，再在 \\(z\\) 上做扩散。后课 CFG 默认生成器已经活在这个 \\(z\\) 上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素扩散的空间是 \\(H\\times W\\times 3\\)。VAE 编码器 \\(E\\) 给出 \\(z=E(x)\\)，解码器 \\(D\\) 重构 \\(\\hat x=D(z)\\)。与 <a href="/llm/vq-vae">VQ-VAE</a> / <a href="/llm/vqgan">VQGAN</a> 不同：这里的 \\(z\\) 常保持连续（对角高斯后验），不量化成词表。LDM 的关键是：感知损失 + 对抗让 \\(D(z)\\) 够锐，于是潜空间里的生成误差在像素上仍可看。</p><p>连续 \\(z\\) 不能当 softmax 词表，这正是<a href="/llm/continuous-vs-discrete-vision-tokens">连续对离散</a> 在生成侧的选择：扩散/流走连续潜变量；AR 走离散码。</p><p><span class="marginnote">下采样倍数（如 8×）决定 \\(z\\) 的空间格。压太狠，文字与布局先坏——文档生成与理解侧 squish 是同一类信息损失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段：冻好 VAE 后，只训潜空间的 \\(\\epsilon_\\theta(z_t,t,c)\\) 或速度场。条件 \\(c\\) 可以是文本塔（常与 <a href="/llm/clip">CLIP</a> 文本编码器相关，但那是条件接口，不是 LLaVA 那种视觉前缀）。验收：重构 FID 与生成 FID 分开；盯文字可读性，不要只报风景 FID。</p>',9)),(e(),s(m,null,{default:l(()=>[h(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20E%5B%22VAE%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20E%20--%3E%20Z%5B%22%E8%BF%9E%E7%BB%AD%E6%BD%9C%E5%8F%98%E9%87%8F%20z%22%5D%0A%20%20Z%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%E6%88%96%E6%B5%81%22%5D%0A%20%20DIFF%20--%3E%20D%5B%22VAE%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20D%20--%3E%20XHAT%5B%22%E5%83%8F%E7%B4%A0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生成器学的是 \\(p(z)\\)，细节纹理由 \\(D\\) 的先验补全——与 VQGAN 解码器「编造高频」同类。因此潜空间 FID 好看不等于 OCR 忠实。理解用的 <a href="/llm/vit-as-encoder">ViT</a> patch 与生成用的 \\(z\\) 格，分辨率协议往往不同，统一模型必须显式对齐或分塔，见后课 Janus。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VAE 重构天花板仍在。下一课在已有条件扩散上加无分类器引导，不改这个潜空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>潜空间 VAE 把扩散/流从像素挪到连续 \\(z\\)。</li><li>连续 \\(z\\) 服务采样，不是 AR 词表。</li><li>重构天花板限制文字与布局。</li><li>出处：Kingma &amp; Welling VAE；Rombach 等 LDM。</li></ul>',6))])}const B=o(E,[["render",p]]);export{V as __pageData,B as default};
